import type { Period, Room, RoomType } from '@/features/timetable/types';
import { durationBetween } from '@/lib/time';
import type { Shift } from '@/features/academics/types';

/**
 * Period grid and room register for the development mock.
 *
 * The slots themselves are not seeded here — they are generated by `devApi`
 * from the live class, subject and teacher rosters, because a timetable
 * hard-coded against ids would break the moment a class was renamed.
 *
 * Deliberately uneven: the morning shift has a full day with two breaks, the
 * afternoon a shorter one, and the evening shift none at all — so the empty
 * state, the break bands and the gap warnings are all reachable without
 * editing anything.
 */

interface PeriodSeed {
  name: string;
  shift: Shift;
  start: string;
  end: string;
  isBreak?: boolean;
}

const PERIOD_SEED: PeriodSeed[] = [
  { name: 'Assembly', shift: 'morning', start: '08:30', end: '08:45', isBreak: true },
  { name: 'Period 1', shift: 'morning', start: '08:45', end: '09:30' },
  { name: 'Period 2', shift: 'morning', start: '09:30', end: '10:15' },
  { name: 'Period 3', shift: 'morning', start: '10:15', end: '11:00' },
  // A deliberate five-minute changeover after period 3 — the gap notice.
  { name: 'Break', shift: 'morning', start: '11:05', end: '11:25', isBreak: true },
  { name: 'Period 4', shift: 'morning', start: '11:25', end: '12:10' },
  { name: 'Period 5', shift: 'morning', start: '12:10', end: '12:55' },
  { name: 'Lunch', shift: 'morning', start: '12:55', end: '13:35', isBreak: true },
  { name: 'Period 6', shift: 'morning', start: '13:35', end: '14:20' },
  { name: 'Period 7', shift: 'morning', start: '14:20', end: '15:05' },

  { name: 'Period 1', shift: 'afternoon', start: '13:00', end: '13:45' },
  { name: 'Period 2', shift: 'afternoon', start: '13:45', end: '14:30' },
  { name: 'Break', shift: 'afternoon', start: '14:30', end: '14:50', isBreak: true },
  { name: 'Period 3', shift: 'afternoon', start: '14:50', end: '15:35' },
  { name: 'Period 4', shift: 'afternoon', start: '15:35', end: '16:20' },
  { name: 'Period 5', shift: 'afternoon', start: '16:20', end: '17:05' },
];

function buildPeriod(seed: PeriodSeed, index: number, all: PeriodSeed[]): Period {
  // Position within the shift, not within the whole seed.
  const sortOrder = all.filter((entry) => entry.shift === seed.shift).indexOf(seed) + 1;

  return {
    id: index + 1,
    name: seed.name,
    sort_order: sortOrder,
    shift: seed.shift,
    start_time: seed.start,
    end_time: seed.end,
    duration_minutes: durationBetween(seed.start, seed.end) ?? 0,
    is_break: seed.isBreak ?? false,
    // Filled in by the mock once the slots are generated.
    slots_count: 0,
    created_at: '2025-04-01T00:00:00.000000Z',
  };
}

export const periods: Period[] = PERIOD_SEED.map(buildPeriod);

interface RoomSeed {
  name: string;
  code: string;
  type: RoomType;
  building: string | null;
  floor: number | null;
  capacity: number;
  isActive?: boolean;
}

/**
 * Mixed on purpose: rooms too small for a full class, specialist labs, an
 * open ground with no floor, and one closed for repairs — so the capacity
 * warning, the room-type badges and the unavailable state are all reachable.
 */
const ROOM_SEED: RoomSeed[] = [
  { name: 'Block A — 101', code: 'A-101', type: 'classroom', building: 'Block A', floor: 1, capacity: 45 },
  { name: 'Block A — 102', code: 'A-102', type: 'classroom', building: 'Block A', floor: 1, capacity: 45 },
  { name: 'Block A — 103', code: 'A-103', type: 'classroom', building: 'Block A', floor: 1, capacity: 40 },
  { name: 'Block B — 201', code: 'B-201', type: 'classroom', building: 'Block B', floor: 2, capacity: 45 },
  { name: 'Block B — 202', code: 'B-202', type: 'classroom', building: 'Block B', floor: 2, capacity: 45 },
  // Smaller than a full class — trips the capacity warning on the slot form.
  { name: 'Block B — 203', code: 'B-203', type: 'classroom', building: 'Block B', floor: 2, capacity: 24 },
  { name: 'Physics laboratory', code: 'LAB-P', type: 'science_lab', building: 'Science block', floor: 0, capacity: 30 },
  { name: 'Chemistry laboratory', code: 'LAB-C', type: 'science_lab', building: 'Science block', floor: 0, capacity: 30 },
  { name: 'Computer laboratory', code: 'LAB-CS', type: 'computer_lab', building: 'Block C', floor: 1, capacity: 36 },
  { name: 'Library', code: 'LIB', type: 'library', building: 'Block C', floor: 0, capacity: 60 },
  { name: 'Auditorium', code: 'AUD', type: 'hall', building: 'Main block', floor: 0, capacity: 300 },
  { name: 'Art room', code: 'ART', type: 'activity', building: 'Block C', floor: 2, capacity: 30 },
  // No floor — an open space, which is what the nullable column is for.
  { name: 'Playground', code: 'GRND', type: 'ground', building: null, floor: null, capacity: 200 },
  // Closed for repairs: hidden from the picker, kept on the register.
  { name: 'Block D — 301', code: 'D-301', type: 'classroom', building: 'Block D', floor: 3, capacity: 40, isActive: false },
];

export const rooms: Room[] = ROOM_SEED.map((seed, index) => ({
  id: index + 1,
  name: seed.name,
  code: seed.code,
  type: seed.type,
  building: seed.building,
  floor: seed.floor,
  capacity: seed.capacity,
  is_active: seed.isActive ?? true,
  // Both computed by the mock from the slots.
  allocated_periods: 0,
  utilisation_percent: 0,
  created_at: '2025-04-01T00:00:00.000000Z',
}));

export const nextPeriodId = periods.length + 1;
export const nextRoomId = rooms.length + 1;
